Method.Implementation:
  NEW $NAMESPACE
  SET $NAMESPACE = "ITFCOMMON"
  try 
  {
	set repNcid = ""
	set servicePort = ##class(HddCommonService.HddCommonServicePort).%New()

    set servicePort.Location = ..Location

	$$$LOGINFO("GetHddNcidForRep: Rep: " _ rep _ ", Dom: " _ domain _ ", Cnxt: " _ context)

 	Set list = servicePort.getNcidsForRepresentation(rep, domain, context, ..dbEnv) 
 	set prntStr =  "Call returned " _ list.Count()
 	Do ##class(ITFCOMMON.Utility).WriteToFile(prntStr)
 	if (list.Count() < 1)
 	{
	 	   $$$LOGERROR("HDD service: Rep: " _ rep _ ": " _ prntStr)
	 	   Set repNcid = "Unknown"
 	}
 	else
 	{
 	  For cnt=1:1:list.Count() 
 	  {
		  $$$LOGINFO("NCID for : " _ rep _ " = " _ list.GetAt(cnt))

		  Set ced = servicePort.getPreferredSurfaceForm(list.GetAt(cnt), context, ..dbEnv)
		  if $GET(ced)
		  {
		  	$$$LOGINFO("Pref Name in " _ context _ " context for: " _list.GetAt(cnt) _ " = " _ ced.text)
		  	Set repNcid = list.GetAt(cnt)

		  	Quit
		  }

 	  }
      if (repNcid = "")
 	  {
	 	 Set repNcid = list.GetAt(1)
	  }  
 	}
  }

    CATCH exceptionvar
    {
	  Set repNcid = "ERROR"  
	  If $ZERROR["<ZSOAP>" {
	     set errTxt = $System.Status.GetErrorText(%objlasterror)
	     Set repNcid = errTxt
         $$$LOGERROR("Exception in GetHddNcidForRep: " _ errTxt _ ", Excp:" _ exceptionvar.Name _ " " _ exceptionvar.Code _ " " _ exceptionvar.Location)
         $$$LOGERROR($ZERROR)
	  }
	  else
	  {
		  throw exceptionvar
	  }

    }

  NEW $NAMESPACE
  SET $NAMESPACE = "ITFCOMMON"
  try 
  {
 	Set rep = ""
	set servicePort = ##class(HddCommonService.HddCommonServicePort).%New()
  	set servicePort.Location = ..Location
		  Set ced = servicePort.getPreferredSurfaceForm(ncid, context, ..dbEnv)
		  if $GET(ced)
		  {
		   	$$$LOGINFO("Pref Name in context for: " _ ncid _ " in context " _ context _ " = " _ ced.text)
		  	Set rep = ced.text
		  	Quit
		  }
		  else
		  {
			  Set rep = "ERROR" 
		  }

	}  
    CATCH exceptionvar
    {
     Set rep = "ERROR"  
	  If $ZERROR["<ZSOAP>" {
	     set errTxt = $System.Status.GetErrorText(%objlasterror)
	     Set repNcid = errTxt
         $$$LOGERROR("Exception in GetHddRepForNcid " _ errTxt _ ", Excp:" _ exceptionvar.Name _ " " _ exceptionvar.Code _ " " _ exceptionvar.Location)
         $$$LOGERROR($ZERROR)
	  }
	  else
	  {
		  throw exceptionvar
	  }
    }
